const body = $input.first().json.body || $input.first().json;
const callSid = body.CallSid;
const speechResult = body.SpeechResult || null;

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};

if (!staticData.sessions[callSid]) {
  staticData.sessions[callSid] = {
    history: [],
    collected: { name: null, service: null, start_datetime: null, end_datetime: null }
  };
}

const session = staticData.sessions[callSid];

if (speechResult) {
  session.history.push({ role: 'user', text: speechResult });
}

return [{
  json: {
    callSid,
    history: session.history,
    collected: session.collected,
    callerNumber: body.From || ''
  }
}];

const item = $input.first().json;
const history = item.history || [];

const transcript = history.map(h => `${h.role === 'user' ? 'Caller' : 'Receptionist'}: ${h.text}`).join('\n');
const currentDate = new Date().toISOString().split('T')[0];

const systemPrompt = `You are a warm, professional AI phone receptionist for a small business. Your ONLY job on this call is to book an appointment.

You need to collect exactly three things from the caller:
1. Their name
2. The reason/service for the appointment
3. A preferred date and time

Ask ONE short, natural, conversational question at a time. Do not repeat information you already have. Today's date is ${currentDate} - use it to resolve relative dates like "tomorrow" or "next Monday" into real calendar dates.

Once you have all three pieces of information, say a warm one-sentence confirmation back to the caller and set booking_complete to true.

Respond with STRICT JSON only, no markdown, no extra text, in exactly this shape:
{
  "reply": "<what you will say out loud to the caller next>",
  "booking_complete": false,
  "name": null,
  "service": null,
  "start_datetime": null,
  "end_datetime": null
}

Rules:
- start_datetime and end_datetime must be full ISO 8601 timestamps (e.g. 2026-09-22T14:00:00) once known. Default appointment length is 30 minutes.
- Only set booking_complete to true once name, service, start_datetime, and end_datetime are ALL known.
- Keep "reply" short and natural, like a real receptionist speaking on the phone - one or two sentences max.

Conversation so far:
${transcript || '(This is the very first message. Greet the caller warmly and ask how you can help.)'}
`;

return [{
  json: {
    requestBody: {
      contents: [
        { role: 'user', parts: [{ text: systemPrompt }] }
      ],
      generationConfig: { responseMimeType: 'application/json', temperature: 0.4 }
    },
    callSid: item.callSid,
    callerNumber: item.callerNumber
  }
}];

const response = $input.first().json;
const prev = $('Build Gemini Prompt').item.json;

let parsed;
try {
  const text = response.candidates[0].content.parts[0].text;
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { reply: "I'm sorry, could you repeat that?", booking_complete: false };
}

const staticData = $getWorkflowStaticData('global');
const session = staticData.sessions[prev.callSid];

session.history.push({ role: 'model', text: parsed.reply });

session.collected = {
  name: parsed.name || session.collected.name || null,
  service: parsed.service || session.collected.service || null,
  start_datetime: parsed.start_datetime || session.collected.start_datetime || null,
  end_datetime: parsed.end_datetime || session.collected.end_datetime || null
};

return [{
  json: {
    callSid: prev.callSid,
    reply: parsed.reply,
    booking_complete: !!parsed.booking_complete,
    collected: session.collected,
    callerNumber: prev.callerNumber
  }
}];

const reply = $('Parse Gemini Response').item.json.reply;

function escapeXml(str) {
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');
}

const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Joanna">${escapeXml(reply)}</Say>
  <Hangup/>
</Response>`;

return [{ json: { twiml } }];

const item = $input.first().json;

function escapeXml(str) {
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');
}

// IMPORTANT: replace the action URL below with your actual n8n production webhook URL
const webhookUrl = 'https://YOUR-N8N-DOMAIN/webhook/voice-receptionist';

const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Gather input="speech" action="${webhookUrl}" method="POST" speechTimeout="auto" timeout="6">
    <Say voice="Polly.Joanna">${escapeXml(item.reply)}</Say>
  </Gather>
  <Say voice="Polly.Joanna">Sorry, I didn't catch that. Goodbye.</Say>
  <Hangup/>
</Response>`;

return [{ json: { twiml } }];
